const AUDIO_PATH='assets/audio/';
const AUDIO={ready:false,unlocked:false,music:null,ambience:null,zone:'town',sfx:{}};
const SFX_FILES=['ui_click','footstep','sword_hit','hurt','gather','coin','quest','level_up','fish_splash','cook_sizzle','loot_pickup','wood_chop','mine_strike','discover','guard_block','enemy_warning','bow_shot','arcane_bolt','arcane_burst','arquebus_shot','festival_bell'];
function loadSettings(){try{const raw=localStorage.getItem(SETTINGS_KEY),s=raw?JSON.parse(raw):{};return{music:clamp(Number(s.music??.34),0,1),ambience:clamp(Number(s.ambience??.32),0,1),sfx:clamp(Number(s.sfx??.62),0,1),mute:Boolean(s.mute)}}catch{return{music:.34,ambience:.32,sfx:.62,mute:false}}}
function persistSettings(){try{localStorage.setItem(SETTINGS_KEY,JSON.stringify(APP.settings))}catch{}applyAudioSettings()}
function initAudio(){if(AUDIO.ready)return;AUDIO.ready=true;AUDIO.music=new Audio(AUDIO_PATH+'music_port_felin.ogg');AUDIO.music.loop=true;AUDIO.music.preload='auto';AUDIO.ambience=new Audio(AUDIO_PATH+'ambience_town.ogg');AUDIO.ambience.loop=true;AUDIO.ambience.preload='auto';for(const n of SFX_FILES){const a=new Audio(AUDIO_PATH+n+'.ogg');a.preload='auto';AUDIO.sfx[n]=a}applyAudioSettings()}
function applyAudioSettings(){if(!AUDIO.ready)return;const muted=APP.settings.mute;AUDIO.music.volume=muted?0:APP.settings.music;AUDIO.ambience.volume=muted?0:APP.settings.ambience;updateAudioButton()}
function unlockAudio(){initAudio();if(AUDIO.unlocked)return;AUDIO.unlocked=true;AUDIO.music.play().catch(()=>{});AUDIO.ambience.play().catch(()=>{})}
function playSfx(name,scale=1){if(APP.settings.mute||APP.settings.sfx<=0)return;unlockAudio();const base=AUDIO.sfx[name];if(!base)return;const a=base.cloneNode();a.volume=clamp(APP.settings.sfx*scale,0,1);a.play().catch(()=>{})}
function updateAudioZone(){if(!AUDIO.unlocked||!current())return;const next=MAPS[APP.mapId]?.outdoor&&currentWeather()==='rain'?'rain':MAPS[APP.mapId]?.dungeon?'dungeon':APP.mapId==='port_felin'?(current().position.x<690?'town':'wild'):MAPS[APP.mapId]?.outdoor?'wild':'town';if(next===AUDIO.zone)return;AUDIO.zone=next;const old=AUDIO.ambience;const file=next==='rain'?'ambience_rain.ogg':next==='town'?'ambience_town.ogg':next==='wild'?'ambience_wild.ogg':'ambience_dungeon.ogg',replacement=new Audio(AUDIO_PATH+file);replacement.loop=true;replacement.preload='auto';replacement.volume=APP.settings.mute?0:APP.settings.ambience;AUDIO.ambience=replacement;replacement.play().catch(()=>{});if(old){old.pause();old.currentTime=0}}
function toggleMute(){APP.settings.mute=!APP.settings.mute;persistSettings();if(!APP.settings.mute)unlockAudio();toast(APP.settings.mute?'Audio muted.':'Audio on.');updateAudioButton()}
function updateAudioButton(){const b=document.querySelector('[data-audio-toggle]');if(b){b.textContent=APP.settings.mute?'🔇':'🔊';b.title=APP.settings.mute?'Unmute audio':'Mute audio'}}
function isStandalone(){return window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true}
async function promptInstall(){if(!APP.installPrompt){toast(isStandalone()?'Already running as the installed app.':'Install prompt is not available in this browser right now.');return}const p=APP.installPrompt;APP.installPrompt=null;const result=await p.prompt();if(result?.outcome==='accepted')toast('Installing Paws & Plumes…');else toast('Installation cancelled.')}
async function checkForUpdate(){try{if(APP.swRegistration){await APP.swRegistration.update();toast('Checked for an app update.')}}catch{toast('Could not check for an update.')}}
async function refreshAppFiles(){if(!('caches'in window)){location.reload();return}try{for(const k of await caches.keys())if(k.startsWith('paws-plumes-'))await caches.delete(k);if(APP.swRegistration)await APP.swRegistration.update();toast('App files refreshed. Reloading…');setTimeout(()=>location.reload(),450)}catch{location.reload()}}
function installStatusText(){if(isStandalone())return'Installed — this window is running in standalone app mode.';if(APP.installPrompt)return'Ready to install on this device.';return'This browser is not offering a new install prompt. It may already have an older Paws & Plumes install registered, or it may require its browser menu to add the app.'}
function randomRange(a,b){return a+Math.random()*(b-a)}
function addFloater(x,y,text,color='#fff1bd'){APP.motion.floaters.push({x,y,text,color,life:1.05,max:1.05})}
function addBurst(x,y,color='#d8c17a',count=7){for(let i=0;i<count;i++)APP.motion.particles.push({x,y,vx:randomRange(-42,42),vy:randomRange(-58,-18),life:randomRange(.35,.75),max:.75,color,size:randomRange(2,4)})}
function blankSave(){return{version:VERSION,lastCharacterId:null,characters:[]}}
function loadSave(){try{const raw=localStorage.getItem(SAVE_KEY);if(!raw)return blankSave();const x=JSON.parse(raw);if(x&&Array.isArray(x.characters)){x.version=VERSION;return x}return blankSave()}catch{return blankSave()}}
function persist(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(APP.save))}catch{}}
function current(){return APP.save.characters.find(c=>c.id===APP.currentId)||null}
function makeId(){return'cat_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7)}
function clamp(v,a,b){return Math.max(a,Math.min(b,v))} function dist(ax,ay,bx,by){return Math.hypot(ax-bx,ay-by)}
function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function prop(o,n,f=null){const p=(o.properties||[]).find(x=>x.name===n);return p?p.value:f}
function xpNeed(l){return Math.floor(45*Math.pow(l,1.48))} function skillNeed(l){return Math.floor(26*Math.pow(l,1.55))}
function migrateCharacter(c){if(!c)return;c.quests=c.quests||{first_commission:'available'};if(!c.quests.first_commission)c.quests.first_commission='available';if(!c.quests.river_supper)c.quests.river_supper=c.quests.first_commission==='claimed'?'available':'locked';if(!c.quests.iron_and_oak)c.quests.iron_and_oak=c.quests.first_commission==='claimed'?'available':'locked';if(!c.quests.redtail_problem)c.quests.redtail_problem=c.quests.iron_and_oak==='claimed'?'available':'locked';if(!c.quests.beneath_quarry)c.quests.beneath_quarry=c.quests.redtail_problem==='claimed'?'available':'locked';if(!c.quests.long_watch)c.quests.long_watch=c.quests.iron_and_oak==='claimed'?'available':'locked';if(!c.quests.glass_and_thunder)c.quests.glass_and_thunder=c.quests.beneath_quarry==='claimed'?'available':'locked';if(!c.quests.sable_company)c.quests.sable_company=c.quests.redtail_problem==='claimed'?'available':'locked';if(!c.quests.makers_mark)c.quests.makers_mark=c.quests.sable_company==='claimed'?'available':'locked';if(!c.quests.bellkeepers_week)c.quests.bellkeepers_week=c.quests.sable_company==='claimed'?'available':'locked';if(!c.quests.weatherwise_wanderer)c.quests.weatherwise_wanderer=c.quests.first_commission==='claimed'?'available':'locked';c.counters=c.counters||{};c.counters.kills=c.counters.kills||{};c.counters.gathered=c.counters.gathered||{};c.counters.crafted=c.counters.crafted||{};c.counters.found=c.counters.found||{};c.counters.combat=c.counters.combat||{};c.counters.events=c.counters.events||{};for(const k of ['market_trade','guild_contract','river_casts','vale_lavender','weather_rain_casts','weather_mist_herbs','weather_wind_victories'])c.counters.events[k]=Number(c.counters.events[k])||0;c.counters.combat.ranged_kills=Number(c.counters.combat.ranged_kills)||0;c.counters.combat.magic_kills=Number(c.counters.combat.magic_kills)||0;c.world=c.world||{};c.world.enemies=c.world.enemies||{};c.world.resources=c.world.resources||{};c.world.drops=Array.isArray(c.world.drops)?c.world.drops:[];c.world.flags=c.world.flags||{};c.world.chests=c.world.chests||{};c.world.exploredMap=c.world.exploredMap||{};c.world.waypoints=c.world.waypoints||{};if(!('contract'in c.world))c.world.contract=null;if(!Number.isFinite(c.world.timeMinutes))c.world.timeMinutes=480;c.discovered=c.discovered||{port_felin:true};if(c.discovered.port_felin==null)c.discovered.port_felin=true;if(c.quests.first_commission==='claimed'&&c.quests.river_supper==='locked')c.quests.river_supper='available';if(c.quests.first_commission==='claimed'&&c.quests.iron_and_oak==='locked')c.quests.iron_and_oak='available';if(c.quests.iron_and_oak==='claimed'&&c.quests.redtail_problem==='locked')c.quests.redtail_problem='available';if(c.quests.redtail_problem==='claimed'&&c.quests.beneath_quarry==='locked')c.quests.beneath_quarry='available';if(c.quests.iron_and_oak==='claimed'&&c.quests.long_watch==='locked')c.quests.long_watch='available';if(c.quests.beneath_quarry==='claimed'&&c.quests.glass_and_thunder==='locked')c.quests.glass_and_thunder='available';if(c.quests.redtail_problem==='claimed'&&c.quests.sable_company==='locked')c.quests.sable_company='available';if(c.quests.sable_company==='claimed'&&c.quests.makers_mark==='locked')c.quests.makers_mark='available';if(c.quests.sable_company==='claimed'&&c.quests.bellkeepers_week==='locked')c.quests.bellkeepers_week='available';if(c.quests.first_commission==='claimed'&&c.quests.weatherwise_wanderer==='locked')c.quests.weatherwise_wanderer='available';c.skills=c.skills||{};for(const k of Object.keys(SKILL_NAMES))if(!c.skills[k])c.skills[k]={level:1,xp:0};c.maxFocus=Math.max(30,Number(c.maxFocus)||30);c.focus=clamp(Number.isFinite(c.focus)?c.focus:c.maxFocus,0,c.maxFocus+20);c.equipment=c.equipment||{weapon:'worn_rapier',body:null};c.bank=c.bank||{items:{},coins:0};c.bank.items=c.bank.items||{};c.bank.coins=Math.max(0,Number(c.bank.coins)||0);c.world.townFlags=c.world.townFlags||{};c.discipline=DISCIPLINES[c.discipline]?c.discipline:null;if(!c.reputation){let guild=0,bellflower=0;for(const[id,q]of Object.entries(QUESTS))if(c.quests[id]==='claimed'){guild+=q.renown||0;bellflower+=q.favor||0}c.reputation={guild,bellflower,claimedRanks:{}}}else{c.reputation.guild=Math.max(0,Number(c.reputation.guild)||0);c.reputation.bellflower=Math.max(0,Number(c.reputation.bellflower)||0);c.reputation.claimedRanks=c.reputation.claimedRanks||{}};if(!c.world.location||!MAPS[c.world.location])c.world.location='port_felin';for(const d of c.world.drops)if(!d.mapId)d.mapId='port_felin'}
function questState(id){const c=current(),q=QUESTS[id];if(!c||!q)return'locked';const st=c.quests[id];if(st)return st;if(q.unlock&&c.quests[q.unlock]!=='claimed')return'locked';return'available'}
function unlockQuests(){const c=current();if(!c)return;for(const[id,q]of Object.entries(QUESTS))if((c.quests[id]||'locked')==='locked'&&(!q.unlock||c.quests[q.unlock]==='claimed'))c.quests[id]='available'}
function acceptQuest(id){const c=current(),q=QUESTS[id];if(!c||!q||questState(id)!=='available')return;c.quests[id]='active';playSfx('quest',.7);saveCharacter();closeModal();toast(`Quest accepted: ${q.title}`);renderPanel()}
function counterValue(kind,key){return current()?.counters?.[kind]?.[key]||0}
function recordFestivalAction(key,amount=1){const c=current();if(!c)return;c.counters.events=c.counters.events||{};const before=Number(c.counters.events[key])||0;c.counters.events[key]=before+Math.max(0,amount);if(questState('bellkeepers_week')==='active'){const labels={market_trade:'Market Day trade marked',guild_contract:'Guild Muster service marked',river_casts:'River Blessing catch marked',vale_lavender:'Bellflower Fair lavender marked'};if(before===0&&labels[key]){playSfx('quest',.42);toast(labels[key]+'.')}}saveCharacter()}
function recordFieldcraftAction(key){
 if(questState('weatherwise_wanderer')!=='active'||!FIELDCRAFT_TASKS[key])return;
 const c=current(),need=QUESTS.weatherwise_wanderer.requirements.find(r=>r[1]===key)?.[2]||1;
 const count=Math.max(0,Number(c.counters.events[key])||0);
 if(count>=need)return;
 c.counters.events[key]=count+1;
 if(count+1===need){playSfx('quest',.42);toast(`Field ledger: ${FIELDCRAFT_TASKS[key]} complete.`)}
 if(APP.panelTab==='quests')renderPanel();
}
function reputationTier(points,table){let tier=table[0];for(const r of table)if(points>=r.min)tier=r;return tier}
function guildRank(c=current()){return reputationTier(c?.reputation?.guild||0,GUILD_RANKS)}
function valeRank(c=current()){return reputationTier(c?.reputation?.bellflower||0,VALE_RANKS)}
function nextReputationTier(points,table){return table.find(r=>r.min>points)||null}
function addReputation(guild=0,bellflower=0){const c=current();if(!c)return;const beforeGuild=guildRank(c).key,beforeVale=valeRank(c).key;c.reputation.guild=Math.max(0,(c.reputation.guild||0)+guild);c.reputation.bellflower=Math.max(0,(c.reputation.bellflower||0)+bellflower);const afterGuild=guildRank(c),afterVale=valeRank(c);if(afterGuild.key!==beforeGuild){playSfx('level_up',.8);toast(`Guild rank advanced: ${afterGuild.name}.`)}else if(afterVale.key!==beforeVale){playSfx('level_up',.72);toast(`Bellflower standing advanced: ${afterVale.name}.`)}if(guild||bellflower){const parts=[];if(guild)parts.push(`+${guild} Guild Renown`);if(bellflower)parts.push(`+${bellflower} Bellflower Favor`);APP.log=parts.join(' • ')}}
function contractCoinReward(q){const eventBonus=worldEventActive('guild')?0.15:0;return Math.round(q.reward.coins*(1+(guildRank().contract||0)+eventBonus))}
function merchantBuyPrice(base){const fair=worldEventActive('market')?0.05:0;return Math.max(1,Math.round(base*(1-(guildRank().market||0)-fair)))}
function rankRewardAvailable(){const c=current();if(!c)return null;for(const rank of GUILD_RANKS.slice(1))if(c.reputation.guild>=rank.min&&!c.reputation.claimedRanks[rank.key])return rank;return null}
function claimRankReward(){const c=current(),rank=rankRewardAvailable();if(!c||!rank)return;const reward=GUILD_STIPENDS[rank.key];if(!reward)return;c.reputation.claimedRanks[rank.key]=true;c.coins+=reward.coins||0;for(const[k,n]of Object.entries(reward.items||{}))addItem(k,n);playSfx('coin',.65);playSfx('quest',.65);saveCharacter();closeModal();toast(`${rank.name} stipend claimed: +${reward.coins||0} crowns.`);renderPanel();updateHud()}
function reputationSummaryHtml(){const c=current(),g=guildRank(c),v=valeRank(c),gn=nextReputationTier(c.reputation.guild,GUILD_RANKS),vn=nextReputationTier(c.reputation.bellflower,VALE_RANKS),gp=gn?clamp((c.reputation.guild-g.min)/(gn.min-g.min)*100,0,100):100,vp=vn?clamp((c.reputation.bellflower-v.min)/(vn.min-v.min)*100,0,100):100;return`<div class="rep-grid"><div class="rep-card"><div class="rep-head"><strong>Gilded Paw</strong><span>${g.name}</span></div><div class="rep-bar"><span style="width:${gp}%"></span></div><small>${c.reputation.guild} renown${gn?` • ${gn.min-c.reputation.guild} to ${gn.name}`:' • maximum rank'}</small><p>${Math.round((g.contract||0)*100)}% contract bonus • ${Math.round((g.market||0)*100)}% Mercato favor • ${Math.round((g.travel||0)*100)}% faster wayshrines</p></div><div class="rep-card vale"><div class="rep-head"><strong>Bellflower Vale</strong><span>${v.name}</span></div><div class="rep-bar"><span style="width:${vp}%"></span></div><small>${c.reputation.bellflower} favor${vn?` • ${vn.min-c.reputation.bellflower} to ${vn.name}`:' • maximum standing'}</small><p>${v.min>=50?'Maribel’s quartermaster recognizes you.':'Help the vale to earn local privileges.'}</p></div></div>`}
function contractAvailable(id){const c=current(),q=CONTRACTS[id];if(!c||!q)return false;if(q.unlock&&c.quests[q.unlock]!=='claimed')return false;if(q.event&&!worldEventActive(q.event))return false;return true}
function contractProgress(){const c=current(),a=c?.world?.contract;if(!a||!CONTRACTS[a.id])return null;const q=CONTRACTS[a.id],[kind,key,need]=q.counter,now=counterValue(kind,key),done=Math.max(0,now-(a.start||0));return{id:a.id,q,done,need,complete:done>=need,text:`${Math.min(done,need)}/${need} ${key.replaceAll('_',' ')}`}}
function acceptContract(id){const c=current(),q=CONTRACTS[id];if(!c||c.world.contract||!contractAvailable(id))return;const[kind,key]=q.counter;c.world.contract={id,start:counterValue(kind,key),acceptedAt:Date.now()};playSfx('quest',.6);saveCharacter();closeModal();toast(`Guild contract accepted: ${q.title}`);renderPanel()}
function claimContract(){const c=current(),p=contractProgress();if(!c||!p?.complete)return;const coins=contractCoinReward(p.q);c.coins+=coins;addPlayerXp(p.q.reward.xp);addReputation(p.q.renown||0,p.q.favor||0);if(worldEventActive('guild'))recordFestivalAction('guild_contract',1);c.world.contract=null;playSfx('coin',.65);playSfx('quest',.55);saveCharacter();closeModal();toast(`Contract complete: +${coins} crowns, +${p.q.reward.xp} XP${p.q.renown?`, +${p.q.renown} renown`:''}.`);renderPanel();updateHud()}
function abandonContract(){const c=current();if(!c?.world?.contract)return;c.world.contract=null;saveCharacter();closeModal();toast('Guild contract abandoned.');renderPanel()}
const WEATHER={clear:{name:'Fair Skies',icon:'☀',text:'Clear roads and normal conditions.'},rain:{name:'River Rain',icon:'☂',text:'An extra Silver Dace per fishing cast.'},mist:{name:'Low Mist',icon:'≋',text:'Hostile creatures notice you from a shorter distance.'},wind:{name:'Crosswind',icon:'➶',text:'Ranged accuracy −8 percentage points outdoors.'}};
const WEATHER_PERIOD=180; // Three in-game hours per change, fixed for a given region and date.
function weatherAt(minutes,mapId=APP.mapId){
 if(!MAPS[mapId]?.outdoor)return'clear';
 const slot=Math.floor(Math.max(0,minutes)/WEATHER_PERIOD),salt=mapId==='bellflower_vale'?0x5be31:0x37fac;
 let h=(Math.imul(slot+1,1664525)+salt+1013904223)>>>0;
 h^=h>>>16;h=Math.imul(h,2246822519)>>>0;h^=h>>>13;
 const roll=(h>>>0)%100;
 return roll<36?'clear':roll<61?'rain':roll<80?'mist':'wind';
}
function currentWeather(){return weatherAt(worldTotalMinutes(),APP.mapId)}
function weatherDescription(){if(!MAPS[APP.mapId]?.outdoor)return'Sheltered';const w=WEATHER[currentWeather()];return `${w.name}: ${w.text}`}
function weatherForecastHtml(region=APP.mapId){
 const t=worldTotalMinutes();
 if(!MAPS[region]?.outdoor)return'<p class="small muted">Step outdoors to check the open-air forecast.</p>';
 const slots=[0,1,2,3].map(n=>(Math.floor(t/WEATHER_PERIOD)+n)*WEATHER_PERIOD),fmt=t=>`Day ${Math.floor(t/1440)+1} • ${String(Math.floor((t%1440)/60)).padStart(2,'0')}:00`;
 return `<div class="weather-forecast">${slots.map((m,n)=>{const k=weatherAt(m,region),w=WEATHER[k];return `<div class="forecast-row"><strong>${w.icon} ${w.name}</strong><small>${n===0?'Now':fmt(m)}</small><small>${escapeHtml(w.text)}</small></div>`}).join('')}</div><p class="small muted">The forecast follows the in-game clock, not your phone’s weather. Conditions may differ between Port Felin and Bellflower Vale.</p>`;
}
function fieldAlmanacDialogue(){
 const c=current();if(!c)return;
 const regions=['port_felin',...(c.discovered.bellflower_vale?['bellflower_vale']:[])];
 const sections=regions.map(id=>`<div class="panel-title contract-title">${MAPS[id].name}</div>${weatherForecastHtml(id)}`).join('');
 modal('Field Almanac',`<p>Weather changes every three in-game hours. This ledger follows the game clock; it does not use your device’s location.</p>${sections}<p class="small muted">Rain improves dace fishing, mist gives cover from hostile patrols, and crosswind makes archery less certain. Check the town bell for fieldcraft commissions.</p>`);
}
function currentFieldWeather(){const id=MAPS[APP.mapId]?.outdoor?APP.mapId:'port_felin';const kind=weatherAt(worldTotalMinutes(),id);return`${WEATHER[kind].icon} ${WEATHER[kind].name}`}
function syncWeather(){
 const outdoor=Boolean(MAPS[APP.mapId]?.outdoor),kind=outdoor?currentWeather():'sheltered',key=APP.mapId+':'+kind;
 if(APP.motion.weatherKey===key)return;
 const prior=APP.motion.weatherKey;APP.motion.weatherKey=key;
 if(outdoor&&prior&&prior.startsWith(APP.mapId+':')){const w=WEATHER[kind];toast(`Weather changing: ${w.name}.`);APP.log=w.text;updateHud()}
 updateAudioZone();
}
function worldTotalMinutes(){return Math.max(0,Math.floor(current()?.world?.timeMinutes??480))}
function worldMinuteOfDay(){return worldTotalMinutes()%1440}
function worldDayNumber(){return Math.floor(worldTotalMinutes()/1440)+1}
function worldWeekdayIndex(){return Math.floor(worldTotalMinutes()/1440)%WEEKDAYS.length}
function worldDayName(){return WEEKDAYS[worldWeekdayIndex()]}
function formatWorldTime(){const m=worldMinuteOfDay(),h=Math.floor(m/60),mm=String(m%60).padStart(2,'0');return`D${worldDayNumber()} • ${String(h).padStart(2,'0')}:${mm}`}
function formatWorldDateLong(){return`${worldDayName()} • Day ${worldDayNumber()} • ${String(Math.floor(worldMinuteOfDay()/60)).padStart(2,'0')}:${String(worldMinuteOfDay()%60).padStart(2,'0')}`}
function worldHour(){return worldMinuteOfDay()/60}
function worldEventActive(id){const e=WORLD_EVENTS[id];if(!e||worldWeekdayIndex()!==e.day)return false;const h=worldHour();return h>=e.start&&h<e.end}
function currentWorldEvents(){return Object.entries(WORLD_EVENTS).filter(([id])=>worldEventActive(id)).map(([id,e])=>({id,...e}))}
function serviceOpen(kind){const h=SERVICE_HOURS[kind];if(!h)return true;const t=worldHour();return t>=h[0]&&t<h[1]}
function serviceHoursText(kind){const h=SERVICE_HOURS[kind];return h?`${String(h[0]).padStart(2,'0')}:00–${String(h[1]).padStart(2,'0')}:00`:'all hours'}
function nextEventSummary(){const today=worldWeekdayIndex(),h=worldHour();let best=null;for(const[id,e]of Object.entries(WORLD_EVENTS)){let delta=(e.day-today+7)%7;if(delta===0&&h>=e.end)delta=7;const mins=delta*1440+(delta===0?Math.max(0,e.start*60-worldMinuteOfDay()):e.start*60-worldMinuteOfDay());if(best==null||mins<best.mins)best={id,e,mins}}return best}

function nightLevel(){const h=worldHour();if(h>=7&&h<18)return.02;if(h>=20||h<5)return.30;if(h>=18)return.02+(h-18)/2*.28;return.30-(h-5)/2*.28}
function explorationEnabled(mapId=APP.mapId){const m=MAPS[mapId];return Boolean(m&&(m.outdoor||m.dungeon))}
function explorationStore(mapId=APP.mapId){const c=current();if(!c)return{};c.world.exploredMap=c.world.exploredMap||{};c.world.exploredMap[mapId]=c.world.exploredMap[mapId]||{};return c.world.exploredMap[mapId]}
function explorationKey(x,y){return`${Math.floor(x/EXPLORE_STEP)},${Math.floor(y/EXPLORE_STEP)}`}
function mapPointExplored(x,y,mapId=APP.mapId){if(!explorationEnabled(mapId))return true;return Boolean(explorationStore(mapId)[explorationKey(x,y)])}
function revealExploration(force=false){const c=current();if(!c||!APP.map||!explorationEnabled())return false;const cx=Math.floor(c.position.x/EXPLORE_STEP),cy=Math.floor(c.position.y/EXPLORE_STEP),stamp=`${APP.mapId}:${cx},${cy}`;if(!force&&APP.motion.exploreStamp===stamp)return false;APP.motion.exploreStamp=stamp;const store=explorationStore(),radius=MAPS[APP.mapId]?.dungeon?1:1;let changed=false;const cols=Math.ceil(APP.map.width*64/EXPLORE_STEP),rows=Math.ceil(APP.map.height*64/EXPLORE_STEP);for(let y=cy-radius;y<=cy+radius;y++)for(let x=cx-radius;x<=cx+radius;x++){if(x<0||y<0||x>=cols||y>=rows)continue;const k=`${x},${y}`;if(!store[k]){store[k]=1;changed=true}}if(changed){saveCharacterThrottled();drawMiniMap();if(APP.panelTab==='map')renderPanel()}return changed}
function explorationPercent(mapId){const c=current(),store=c?.world?.exploredMap?.[mapId]||{},dims={port_felin:[34,20],bellflower_vale:[30,18],quarry_underworks:[20,14]}[mapId];if(!dims)return 100;const total=Math.ceil(dims[0]*64/EXPLORE_STEP)*Math.ceil(dims[1]*64/EXPLORE_STEP);return Math.min(100,Math.round(Object.keys(store).length/total*100))}
function waypointUnlocked(id){return Boolean(current()?.world?.waypoints?.[id])}
function activateWaypoint(o){const c=current(),id=String(prop(o,'waypoint_id',''));if(!c||!WAYPOINTS[id])return null;c.world.waypoints=c.world.waypoints||{};if(!c.world.waypoints[id]){c.world.waypoints[id]=true;playSfx('discover',.8);addPlayerXp(10);toast(`Wayshrine activated: ${WAYPOINTS[id].name}.`);saveCharacter();if(APP.panelTab==='map')renderPanel()}return id}
function travelMinutes(from,to){if(from===to)return 0;const base=((from==='port_felin'&&to==='old_quarry')||(from==='old_quarry'&&to==='port_felin'))?25:55;return Math.max(10,Math.round(base*(1-(guildRank().travel||0))))}
async function fastTravelTo(fromId,toId){const c=current(),dest=WAYPOINTS[toId];if(!c||!dest||!waypointUnlocked(fromId)||!waypointUnlocked(toId)||APP.mapLoading)return;if(APP.combat.enemyId){toast('You cannot use a wayshrine while fighting.');return}closeModal();const fade=document.getElementById('mapFade');APP.mapLoading=true;clearNavigation();APP.pendingInteraction=null;APP.selectedObjectId=null;if(fade)fade.classList.add('active');await new Promise(r=>setTimeout(r,160));c.world.timeMinutes=c.world.timeMinutes+travelMinutes(fromId,toId);c.world.location=dest.mapId;c.position={x:dest.x,y:dest.y};playSfx('discover',.65);try{await loadMap(dest.mapId);APP.log=`Wayshrine travel: ${WAYPOINTS[fromId].name} → ${dest.name}.`;toast(`Arrived at ${dest.name}.`);updateHud()}finally{APP.mapLoading=false;if(fade)requestAnimationFrame(()=>fade.classList.remove('active'))}}
function wayshrineDialogue(o){if(APP.combat.enemyId){toast('You cannot use a wayshrine while fighting.');return}const here=activateWaypoint(o);if(!here)return;const c=current(),cards=Object.entries(WAYPOINTS).map(([id,w])=>{const unlocked=waypointUnlocked(id),currentNode=id===here;return`<div class="quest-item ${unlocked?'complete':''}"><strong>${w.name}${currentNode?' • HERE':''}</strong><p>${w.desc}</p><button class="game-btn ${currentNode?'dark':'teal'}" data-fast-travel="${id}" ${!unlocked||currentNode?'disabled':''}>${currentNode?'Current shrine':unlocked?`Travel • ${travelMinutes(here,id)} min`:'Not activated'}</button></div>`}).join('');modal('Guild Wayshrine Network',`<p>The bronze paw grows warm. Only shrines you have personally activated can answer the route.</p><div class="contract-list">${cards}</div>`);modalLayer.querySelectorAll('[data-fast-travel]').forEach(b=>b.addEventListener('click',()=>fastTravelTo(here,b.dataset.fastTravel)))}
function atlasLocations(){const c=current();return ATLAS_LOCATIONS.filter(a=>c?.discovered?.[a.key])}
function routeAtlasLocation(key){const a=ATLAS_LOCATIONS.find(x=>x.key===key);if(!a)return;if(a.mapId!==APP.mapId){toast('That location is on another map. Use a road or activated wayshrine.');return}if(MAPS[APP.mapId]?.indoor&&!MAPS[APP.mapId]?.dungeon){toast('Step outside before setting a world route.');return}if(setNavigation(a.x,a.y,34,null,true,false)){toast(`Route set: ${a.name}.`);document.getElementById('sidePanel')?.classList.remove('mobile-open')}}
function areaInfoAt(x,y){if(APP.mapId==='bellflower_vale'){if(x<620)return{key:'bellflower_gate',name:'Bellflower Gate',sub:'Guild tollhouse • lavender fields'};if(y<430&&x>850)return{key:'old_aqueduct',name:'Old Aqueduct',sub:'Ruins • rich iron • Sable scouts'};if(x>1050&&y>610)return{key:'sable_camp',name:'Sable Company Camp',sub:'Pikemen • arquebusiers • Captain Vellum'};return{key:'bellflower_vale',name:'Bellflower Vale',sub:'Fields • old road • dangerous mercenaries'}}if(APP.mapId!=='port_felin'){const m=MAPS[APP.mapId]||MAPS.port_felin;return{key:APP.mapId,name:m.name,sub:m.sub}}if(x<700)return{key:'port_felin',name:'Port Felin',sub:'Guild streets • shops • Warm Saucer'};if(x<1536)return{key:'south_road',name:'South Road & Riverlands',sub:'Bandits • fishing • vineyards'};if(y<520)return{key:'old_quarry',name:'Old Quarry',sub:'Rich iron • Mining 3 • Redtail gang'};if(y>700)return{key:'mosswood',name:'Mosswood',sub:'Old oaks • Woodcutting 3 • dangerous wildlife'};return{key:'eastroad',name:'Eastroad',sub:'Beyond the Stone Bridge • tougher enemies'}}
