function addProjectile(x,y,tx,ty,color='#f4ddb0'){APP.motion.projectiles.push({x,y,tx,ty,life:.24,max:.24,color})}
function updateEffects(dt){for(const q of APP.motion.projectiles)q.life-=dt;APP.motion.projectiles=APP.motion.projectiles.filter(q=>q.life>0);for(const f of APP.motion.floaters){f.life-=dt;f.y-=26*dt}APP.motion.floaters=APP.motion.floaters.filter(f=>f.life>0);for(const p of APP.motion.particles){if(p.ambient){p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.x>APP.map.width*64+20)p.x=-20;continue}p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=72*dt}APP.motion.particles=APP.motion.particles.filter(p=>p.ambient||p.life>0)}
function drawCloudShadows(ctx){if(MAPS[APP.mapId]?.indoor)return;const w=APP.map.width*64,t=APP.motion.worldTime;ctx.save();ctx.globalAlpha=.065;ctx.fillStyle='#233a35';for(let i=0;i<4;i++){const x=((t*18+i*430)%(w+500))-250,y=120+i*210;ctx.beginPath();ctx.ellipse(x,y,150,48,.12,0,Math.PI*2);ctx.ellipse(x+110,y+20,115,38,-.1,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawAmbientParticles(ctx){for(const p of APP.motion.particles){if(!p.ambient)continue;ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size)}}
function drawEffects(ctx){for(const q of APP.motion.projectiles){const p=1-q.life/q.max,x=q.x+(q.tx-q.x)*p,y=q.y+(q.ty-q.y)*p,ang=Math.atan2(q.ty-q.y,q.tx-q.x);ctx.save();ctx.strokeStyle=q.color;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-Math.cos(ang)*13,y-Math.sin(ang)*13);ctx.lineTo(x,y);ctx.stroke();ctx.translate(x,y);ctx.rotate(ang);ctx.fillStyle=q.color;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(-7,-4);ctx.lineTo(-7,4);ctx.closePath();ctx.fill();ctx.restore()}for(const p of APP.motion.particles){if(p.ambient)continue;ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size)}ctx.globalAlpha=1;ctx.textAlign='center';ctx.font='bold 14px Georgia';for(const f of APP.motion.floaters){ctx.globalAlpha=clamp(f.life/f.max,0,1);ctx.fillStyle=f.color;ctx.fillText(f.text,f.x,f.y)}ctx.globalAlpha=1}
function drawSpeech(ctx,text,x,y){ctx.save();ctx.font='11px system-ui,sans-serif';const w=Math.min(150,ctx.measureText(text).width+16);ctx.fillStyle='rgba(246,236,204,.94)';ctx.strokeStyle='rgba(55,47,37,.85)';ctx.lineWidth=1;ctx.fillRect(x-w/2,y-18,w,20);ctx.strokeRect(x-w/2,y-18,w,20);ctx.fillStyle='#342d25';ctx.textAlign='center';ctx.fillText(text,x,y-4);ctx.restore()}
function drawWeatherOverlay(ctx,w,h){
 if(!MAPS[APP.mapId]?.outdoor)return;
 const kind=currentWeather(),t=APP.motion.worldTime,reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;
 if(kind==='clear')return;
 ctx.save();
 if(kind==='rain'){
   ctx.fillStyle='rgba(48,72,90,.09)';ctx.fillRect(0,0,w,h);
   ctx.strokeStyle='rgba(188,216,222,.44)';ctx.lineWidth=1.35;ctx.beginPath();
   for(let i=0;i<Math.min(125,Math.round(w*h/2400));i++){
     const speed=reduced?0:t*310,side=reduced?0:t*54;
     const x=((i*97+side+i*i*7)%(w+70))-35,y=((i*73+speed+i*31)%(h+70))-35;
     ctx.moveTo(x,y);ctx.lineTo(x-8,y+19);
   }
   ctx.stroke();
 }else if(kind==='mist'){
   ctx.fillStyle='rgba(205,213,195,.12)';ctx.fillRect(0,0,w,h);
   for(let i=0;i<4;i++){const shift=reduced?0:Math.sin(t*.14+i)*24,g=ctx.createLinearGradient(0,i*h/4,0,(i+1)*h/4);g.addColorStop(0,'rgba(209,223,216,0)');g.addColorStop(.5,'rgba(209,223,216,.14)');g.addColorStop(1,'rgba(209,223,216,0)');ctx.fillStyle=g;ctx.fillRect(shift-25,i*h/4,w+50,h/4)}
 }else if(kind==='wind'){
   ctx.strokeStyle='rgba(230,219,162,.37)';ctx.lineWidth=1.4;ctx.beginPath();
   for(let i=0;i<16;i++){const x=((i*173+(reduced?0:t*100))%(w+100))-45,y=(i*47)%h;ctx.moveTo(x,y);ctx.quadraticCurveTo(x+15,y-7,x+36,y-3)}ctx.stroke();
 }
 ctx.restore();
}
function drawLightTint(ctx,w,h){if(MAPS[APP.mapId]?.dungeon){const c=current(),px=c.position.x-APP.camera.x,py=c.position.y-APP.camera.y;ctx.save();const g=ctx.createRadialGradient(px,py,95,px,py,350);g.addColorStop(0,'rgba(8,12,15,.03)');g.addColorStop(.48,'rgba(8,12,15,.18)');g.addColorStop(1,'rgba(5,8,10,.58)');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.restore();return}const alpha=MAPS[APP.mapId]?.indoor?Math.min(.08,nightLevel()*.22):nightLevel();if(alpha<=.025)return;ctx.save();ctx.fillStyle=`rgba(18,29,49,${alpha})`;ctx.fillRect(0,0,w,h);ctx.restore()}
