function objectCenter(o){if(o?.type==='drop')return{x:o.x,y:o.y};const m=APP.motion.actors[o.id];if(m&&(o.type==='npc'||o.type==='enemy'))return{x:m.x,y:m.y};return{x:o.x+(o.width||0)/2,y:o.y+(o.height||0)/2}}
function objectById(id){return worldObjects().find(o=>String(o.id)===String(id))||mapDrops().find(d=>String(d.id)===String(id))||null}
function drawMiniMap(){if(!APP.map||!APP.miniCanvas)return;const ctx=APP.miniCanvas.getContext('2d'),w=APP.miniCanvas.width,h=APP.miniCanvas.height,dpr=Math.min(window.devicePixelRatio||1,2);ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,w,h);const sx=w/(APP.map.width*64),sy=h/(APP.map.height*64),ground=APP.map.layers.find(l=>l.name==='Ground'),colors=MAPS[APP.mapId]?.indoor?['','#8f704d','#9b9585','#3d322b','#714044','#777168','#211d1a']:['','#71885b','#9d9078','#5f8f93','#a48661','#9a8a4c','#40553d'];for(let y=0;y<APP.map.height;y++)for(let x=0;x<APP.map.width;x++){ctx.fillStyle=colors[ground.data[y*APP.map.width+x]]||'#777';ctx.fillRect(x*64*sx,y*64*sy,64*sx+1,64*sy+1)}const c=current();for(const o of worldObjects()){if(!objectIsActive(o))continue;if(o.type==='enemy'&&!c?.world?.enemies[o.id]?.alive)continue;if(!['npc','enemy','resource','landmark'].includes(o.type))continue;const lk=prop(o,'kind');if(o.type==='landmark'&&!['locked_gate','supply_chest','cache_chest','boss_chest','waystone','vale_shrine','calendar_bell','market_stall'].includes(lk))continue;const p=objectCenter(o);if(!mapPointExplored(p.x,p.y))continue;ctx.fillStyle=o.type==='enemy'?'#a9534f':o.type==='npc'?'#e0c667':o.type==='landmark'?(lk==='waystone'||lk==='vale_shrine'?'#8fd4d0':'#d2ad64'):prop(o,'resource')==='river_dace'?'#8dc4cf':'#91b36f';ctx.beginPath();ctx.arc(p.x*sx,p.y*sy,(lk==='waystone'||lk==='vale_shrine'?3:2.1)*dpr,0,Math.PI*2);ctx.fill()}for(const d of mapDrops()){if(!mapPointExplored(d.x,d.y))continue;ctx.fillStyle='#f0cf63';ctx.fillRect(d.x*sx-1.5*dpr,d.y*sy-1.5*dpr,3*dpr,3*dpr)}if(explorationEnabled()){const store=explorationStore(),cols=Math.ceil(APP.map.width*64/EXPLORE_STEP),rows=Math.ceil(APP.map.height*64/EXPLORE_STEP);ctx.save();ctx.fillStyle='rgba(9,12,13,.83)';ctx.strokeStyle='rgba(171,151,101,.08)';ctx.lineWidth=Math.max(1,dpr*.55);for(let cy=0;cy<rows;cy++)for(let cx=0;cx<cols;cx++){if(store[`${cx},${cy}`])continue;const rx=cx*EXPLORE_STEP*sx,ry=cy*EXPLORE_STEP*sy,rw=Math.min(EXPLORE_STEP,APP.map.width*64-cx*EXPLORE_STEP)*sx,rh=Math.min(EXPLORE_STEP,APP.map.height*64-cy*EXPLORE_STEP)*sy;ctx.fillRect(rx,ry,rw+1,rh+1);ctx.strokeRect(rx,ry,rw,rh)}ctx.restore()}if(c){ctx.fillStyle='#fff0a2';ctx.strokeStyle='#2e2720';ctx.lineWidth=1.5*dpr;ctx.beginPath();ctx.arc(c.position.x*sx,c.position.y*sy,4*dpr,0,Math.PI*2);ctx.fill();ctx.stroke()}}

function worldPointer(e){if(!APP.worldReady||APP.mapLoading)return;APP.canvas.focus({preventScroll:true});const r=APP.canvas.getBoundingClientRect(),wx=APP.camera.x+(e.clientX-r.left)*(APP.canvas._cssW/r.width),wy=APP.camera.y+(e.clientY-r.top)*(APP.canvas._cssH/r.height),o=pickObject(wx,wy);if(o){APP.selectedObjectId=o.id;const ctr=objectCenter(o),c=current();if(o.type==='enemy'){clearNavigation();startCombat(o)}else if(dist(c.position.x,c.position.y,ctr.x,ctr.y)<110){clearNavigation();interactObject(o)}else{APP.pendingInteraction=o.id;setNavigation(ctr.x,ctr.y,88,o.id,false)}}else{APP.selectedObjectId=null;APP.pendingInteraction=null;APP.combat.enemyId=null;setNavigation(wx,wy,0,null,true);updateHud()}}
function pickObject(x,y){const c=current(),now=Date.now();for(const d of [...mapDrops()].reverse())if(dist(x,y,d.x,d.y)<34)return d;const objs=[...worldObjects()].reverse();for(const o of objs){if(o.type==='spawn'||o.type==='building'||o.type==='obstacle'||!objectIsActive(o))continue;if(o.type==='enemy'&&!c.world.enemies[o.id]?.alive)continue;if(o.type==='resource'&&c.world.resources[o.id]?.readyAt>now)continue;const ctr=objectCenter(o);if(dist(x,y,ctr.x,ctr.y)<38)return o}return null}
function interactObject(o){if(!o)return;APP.selectedObjectId=o.id;if(o.type==='drop')pickupDrop(o);else if(o.type==='npc')interactNpc(prop(o,'kind'),o);else if(o.type==='resource')gatherResource(o);else if(o.type==='enemy')startCombat(o);else if(o.type==='door')transitionMap(o);else if(o.type==='landmark')interactLandmark(o)}
function chestKey(o){return`${APP.mapId}:${prop(o,'chest_id',o.id)}`}
function chestIsOpened(o){return Boolean(current()?.world?.chests?.[chestKey(o)])}
function openDungeonChest(o,kind){const c=current();if(chestIsOpened(o)){toast('This chest has already been searched.');return}if(kind==='boss_chest'&&(c.counters.kills.rat_captain||0)<1){toast('Heavy chain still binds the strongbox. Underboss Vetch has the clasp key.');return}const rewards=kind==='supply_chest'?{coins:18,items:{bread:2,healing_tonic:1}}:kind==='cache_chest'?{coins:28,items:{iron_ore:3,healing_tonic:1,rat_token:1}}:{coins:48,items:{guild_seal:1,rat_token:2}};c.world.chests[chestKey(o)]=true;c.coins+=rewards.coins;for(const[k,n]of Object.entries(rewards.items))addItem(k,n);if(kind==='boss_chest')c.counters.found.guild_seal=(c.counters.found.guild_seal||0)+1;playSfx('loot_pickup',1);playSfx('coin',.55);const ctr=objectCenter(o);addFloater(ctr.x,ctr.y-35,`+${rewards.coins} ◈`,'#f6d66d');APP.log=kind==='boss_chest'?'Recovered the lost Gilded Paw seal from the strongbox.':'You search the old quarry chest.';saveCharacter();renderPanel();updateHud();toast(APP.log)}
function unlockDungeonGate(o){const c=current(),flag=prop(o,'flag','quarry_gate'),key=prop(o,'key','quarry_key');if(c.world.flags[flag]){toast('The quarry gate is already unlocked.');return}if(countItem(key)<1){toast(`The gate needs a heavy brass key. A foreman below may carry one.`);return}removeItem(key,1);c.world.flags[flag]=true;playSfx('mine_strike',.55);const ctr=objectCenter(o);addFloater(ctr.x,ctr.y-40,'GATE UNLOCKED','#f1d17b');clearNavigation();saveCharacter();renderPanel();toast('The old iron gate grinds open.')}

function openValeChest(o){const c=current();if(chestIsOpened(o)){toast('The Sable supply chest has already been searched.');return}if((c.counters.kills.vale_captain||0)<1){toast('Captain Vellum still has the chest key.');return}c.world.chests[chestKey(o)]=true;c.coins+=52;addItem('lavender',2);addItem('healing_tonic',1);addItem('sable_badge',1);playSfx('loot_pickup',1);playSfx('coin',.55);const ctr=objectCenter(o);addFloater(ctr.x,ctr.y-35,'+52 ◈ • Vale cache','#f6d66d');saveCharacter();renderPanel();updateHud();toast('You recover the Sable Company field cache.')}
function interactLandmark(o){const kind=prop(o,'kind');if(kind==='waystone'||kind==='vale_shrine')wayshrineDialogue(o);else if(kind==='calendar_bell')calendarDialogue();else if(kind==='market_stall')marketStallDialogue();else if(kind==='contract_board')contractBoardDialogue();else if(kind==='masterwork_bench')masterworkDialogue();else if(kind==='cook_hearth')hearthDialogue();else if(kind==='inn_bed')bedDialogue();else if(kind==='forge')blacksmithDialogue();else if(kind==='guild_ledger')reputationDialogue();else if(kind==='price_slate'){modal('Mercato Price Slate',`<p>Today’s chalk marks favor iron, pelts and medicinal herbs. Neri pays less than retail, but unlike the guild he buys nearly anything useful.</p>`)}else if(kind==='bank_chest')bankDialogue();else if(kind==='bank_ledger')showTownNote('exchange');else if(kind==='bellflower_marker')showTownNote('bellflower_vale');else if(kind==='vale_ruins')modal('Old Aqueduct',`<p>The aqueduct carried spring water toward Port Felin before the river mills replaced it. Powder smoke blackens several arches where the Sable Company practices.</p>`);else if(kind==='vale_camp')modal('Sable Company Camp',`<p>Black pennants mark a disciplined mercenary camp. Pikes face the road while arquebusiers hold the higher ground.</p>`);else if(kind==='vale_chest')openValeChest(o);else if(kind==='supply_chest'||kind==='cache_chest'||kind==='boss_chest')openDungeonChest(o,kind);else if(kind==='locked_gate')unlockDungeonGate(o);else if(kind==='old_guild_mark')modal('Old Gilded Paw Mark',`<p>A brass paw-and-plume emblem is mortared into the rock. The quarry was guild property long before the upper workings were abandoned.</p>`);else if(kind==='collapsed_lift')modal('Collapsed Lift',`<p>The old ore lift is ruined. Its chain vanishes into a black shaft; restoring it would take more than a field repair.</p>`);else if(kind==='dungeon_notice')modal('Water-Stained Notice',`<p>“Underworks closed by order of the Gilded Paw. Missing seal and ledgers remain property of the guild.”</p>`);else if(kind==='quarry_tunnel')toast('The Underworks stair descends beside the old quarry face.');else toast(o.name)}
function interactNpc(kind,o){APP.combat.enemyId=null;if(SERVICE_HOURS[kind]&&!serviceOpen(kind)){scheduleClosedDialogue(kind,o);return}if(kind==='guildmaster')guildDialogue(o);else if(kind==='blacksmith')blacksmithDialogue(o);else if(kind==='merchant')merchantDialogue(o);else if(kind==='apothecary')apothecaryDialogue(o);else if(kind==='innkeeper')innkeeperDialogue(o);else if(kind==='quarrymaster')quarrymasterDialogue(o);else if(kind==='banker')bankerDialogue(o);else if(kind==='vale_warden')valeWardenDialogue(o);else if(kind==='flavor_guild')modal(o.name,`<p>“If Luca asks, every ledger is exactly where it belongs. If he doesn’t ask, they are also exactly where they belong.”</p>`);else if(kind==='flavor_inn')modal(o.name,`<p>“I know six songs about heroic mousers and eleven about cats who claimed to be heroic mousers.”</p>`);else if(kind==='flavor_bank')modal(o.name,`<p>“Count it twice, stamp it once. That is how we keep foxes out of the arithmetic.”</p>`)}

function disciplineDialogue(){const c=current();const cards=Object.entries(DISCIPLINES).map(([id,d])=>{const unlocked=disciplineUnlocked(id,c),active=c.discipline===id;return`<div class="quest-item ${active?'complete':''}"><strong>${d.name}${active?' • ACTIVE':''}</strong><p>${d.desc}</p><p class="small muted">Requires ${disciplineReqText(id)}</p><button class="game-btn ${active?'dark':'teal'}" data-discipline="${id}" ${!unlocked||active?'disabled':''}>${active?'Active':unlocked?'Adopt discipline':'Locked'}</button></div>`}).join('');modal('Guild Combat Disciplines',`<p>“A discipline is emphasis, not a class,” Luca says. “Train everything you like. When you want a different emphasis, come back and change it.”</p><div class="contract-list">${cards}</div><div class="form-actions"><button class="game-btn dark" data-discipline="none" ${c.discipline?'':'disabled'}>Train without a discipline</button></div>`);modalLayer.querySelectorAll('[data-discipline]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.discipline;if(id!=='none'&&!disciplineUnlocked(id,c))return;c.discipline=id==='none'?null:id;c.focus=Math.min(c.focus,playerFocusMax());saveCharacter();closeModal();toast(c.discipline?`${DISCIPLINES[c.discipline].name} discipline active.`:'Combat discipline cleared.');renderPanel();updateHud()}))}
function valeWardenDialogue(){const c=current(),st=questState('sable_company'),prog=questProgress('sable_company'),vr=valeRank(c);let quest='';if(st==='available')quest=`<button class="game-btn gold" data-accept-vale>Accept “Terms of the Vale”</button>`;else if(st==='active'&&prog.complete)quest=`<button class="game-btn gold" data-claim-vale>Turn in “Terms of the Vale”</button>`;else if(st==='active')quest=`<button class="game-btn dark" disabled>Terms of the Vale: ${prog.text}</button>`;else quest=`<button class="game-btn dark" disabled>Bellflower toll line cleared</button>`;const greeting=vr.min>=175?'“Steward. The vale is quieter because your paw keeps appearing where trouble starts.”':vr.min>=100?'“You are a familiar sight now. Growers ask whether you are on patrol before they ask whether the road is safe.”':vr.min>=50?'“Bellflower remembers who stood against the Sables. You have friends here now.”':'“The vale belongs to growers and drovers, not whichever company plants the tallest pike. The Sables have forgotten that.”';const valeFair=worldEventActive('vale'),teaPrice=valeFair?6:8,rationPrice=valeFair?11:14;const quarter=vr.min>=50?`<h3 class="trade-heading">Vale Quartermaster${valeFair?' • FAIR PRICES':''}</h3><div class="shop-row"><div class="icon">🫖</div><div class="copy"><strong>Bellflower Lavender Tea</strong><small>Restores health and Focus • Vale Ally</small></div><button class="game-btn teal" data-vale-buy="lavender_tea" data-price="${teaPrice}">${teaPrice} ◈</button></div>${vr.min>=100?`<div class="shop-row"><div class="icon">🥧</div><div class="copy"><strong>Vale Field Ration</strong><small>Restores 18 health • Friend of the Vale</small></div><button class="game-btn" data-vale-buy="vale_ration" data-price="${rationPrice}">${rationPrice} ◈</button></div>`:''}`:'';modal('Warden Maribel',`<p>${greeting}</p><p class="small muted">Bellflower standing: <strong>${vr.name}</strong> • ${c.reputation.bellflower} favor</p><div class="dialogue-options">${quest}<button class="game-btn teal" data-vale-lore>Ask about Bellflower Vale</button></div>${quarter}`);const a=modalLayer.querySelector('[data-accept-vale]');if(a)a.addEventListener('click',()=>acceptQuest('sable_company'));const q=modalLayer.querySelector('[data-claim-vale]');if(q)q.addEventListener('click',()=>claimQuest('sable_company'));modalLayer.querySelector('[data-vale-lore]').addEventListener('click',()=>showTownNote('bellflower_vale'));modalLayer.querySelectorAll('[data-vale-buy]').forEach(b=>b.addEventListener('click',()=>{buyItem(b.dataset.valeBuy,Number(b.dataset.price));closeModal();valeWardenDialogue()}))}
function contractBoardDialogue(){const c=current(),active=contractProgress();if(active){const action=active.complete?`<button class="game-btn gold" data-claim-contract>Turn in contract</button>`:`<button class="game-btn dark" disabled>Progress: ${active.text}</button>`;modal('Gilded Paw Contract Board',`<p><strong>${active.q.title}</strong></p><p>${active.q.text}</p><p class="small muted">Current ${guildRank().name} payout: ${contractCoinReward(active.q)} ◈ • ${active.q.reward.xp} XP${active.q.renown?` • +${active.q.renown} renown`:''}</p><div class="dialogue-options">${action}<button class="game-btn danger" data-abandon-contract>Abandon contract</button></div>`);const q=modalLayer.querySelector('[data-claim-contract]');if(q)q.addEventListener('click',claimContract);modalLayer.querySelector('[data-abandon-contract]').addEventListener('click',abandonContract);return}const cards=Object.entries(CONTRACTS).filter(([id])=>contractAvailable(id)).map(([id,q])=>`<button class="contract-card" data-contract="${id}"><strong>${q.title}</strong><span>${q.text}</span><small>Reward: ${contractCoinReward(q)} ◈ • ${q.reward.xp} XP${q.renown?` • +${q.renown} renown`:''}${q.favor?` • +${q.favor} vale favor`:''}</small></button>`).join('');modal('Gilded Paw Contract Board',`<p>Guild contracts are repeatable work, not daily chores. Take one whenever you want a focused grind.</p>${worldEventActive('guild')?'<p class="small muted"><strong>Guild Muster:</strong> contract coin payouts are 15% richer today.</p>':''}<div class="contract-list">${cards}</div>`);modalLayer.querySelectorAll('[data-contract]').forEach(b=>b.addEventListener('click',()=>acceptContract(b.dataset.contract)))}
function learnTownNote(id){const c=current(),note=TOWN_NOTES[id];if(!c||!note)return false;c.world.townFlags=c.world.townFlags||{};const fresh=!c.world.townFlags[id];c.world.townFlags[id]=true;saveCharacter();if(fresh)toast(`Town note recorded: ${note.title}.`);renderPanel();return fresh}
function showTownNote(id){const note=TOWN_NOTES[id];if(!note)return;learnTownNote(id);modal(note.title,`<p>${note.text}</p><p class="small muted">Recorded under Town Notes in your journal.</p>`)}
function reputationDialogue(){const c=current(),reward=rankRewardAvailable();modal('Guild Standing',`${reputationSummaryHtml()}<p class="small muted">Permanent commissions and repeatable contracts build Gilded Paw Renown. Bellflower Favor is local and grows mainly through service in the vale.</p>${reward?`<div class="quest-item complete"><strong>${reward.name} stipend available</strong><p>Luca has a rank stipend recorded for your new standing.</p><button class="game-btn gold" data-rank-stipend>Claim stipend</button></div>`:''}<div class="dialogue-options"><button class="game-btn dark" data-standing-note>Record how guild standing works</button></div>`);const r=modalLayer.querySelector('[data-rank-stipend]');if(r)r.addEventListener('click',claimRankReward);modalLayer.querySelector('[data-standing-note]').addEventListener('click',()=>showTownNote('guild_standing'))}
function guildDialogue(o){const c=current(),st=questState('first_commission'),prog=questProgress('first_commission'),gr=guildRank(c);let extra='';if(st==='available')extra=`<button class="game-btn gold" data-accept-quest="first_commission">Accept “A Paw on the Roads”</button>`;else if(st==='active'&&prog.complete)extra=`<button class="game-btn gold" data-claim-quest="first_commission">Turn in commission</button>`;else if(st==='active')extra=`<button class="game-btn dark" disabled>Commission: ${prog.text}</button>`;else extra=`<button class="game-btn dark" disabled>Road commission completed</button>`;const east=c.quests.first_commission==='claimed'?`<button class="game-btn teal" data-guild-east>Ask about the Eastroad</button>`:'';const greeting=gr.min>=350?'“Gilded Warden. At this point I mostly tell other cats which problems you have already solved.”':gr.min>=200?'“Charterblade. The council has begun using your name as shorthand for problems that should actually get finished.”':gr.min>=100?'“Roadwarden. Good. I have work that requires someone the caravans already recognize.”':gr.min>=40?'“Guild Paw. You have stopped being a promising stranger and become one of my staffing problems.”':'“A guildmaster mostly points capable paws toward problems. Which problem interests you?”';modal('Guildmaster Luca',`<div class="dialogue-speaker"><img src="assets/world/portrait_orange.png" alt="Guildmaster Luca"><div><span class="caps">GILDED PAW GUILD • ${gr.name.toUpperCase()}</span><strong>Guildmaster Luca</strong></div></div><p>${greeting}</p><div class="dialogue-options">${extra}<button class="game-btn gold" data-guild-standing>Review guild standing</button><button class="game-btn" data-guild-charter>Ask about Port Felin’s charter</button>${east}<button class="game-btn teal" data-guild-disciplines>Discuss combat disciplines</button><button class="game-btn dark" data-close3>Farewell</button></div>`);const a=modalLayer.querySelector('[data-accept-quest]');if(a)a.addEventListener('click',()=>acceptQuest('first_commission'));const q=modalLayer.querySelector('[data-claim-quest]');if(q)q.addEventListener('click',()=>claimQuest('first_commission'));modalLayer.querySelector('[data-guild-standing]').addEventListener('click',reputationDialogue);modalLayer.querySelector('[data-guild-charter]').addEventListener('click',()=>showTownNote('guild_charter'));const e=modalLayer.querySelector('[data-guild-east]');if(e)e.addEventListener('click',()=>showTownNote('eastroad'));modalLayer.querySelector('[data-guild-disciplines]').addEventListener('click',disciplineDialogue);modalLayer.querySelector('[data-close3]').addEventListener('click',closeModal)}
