function bankerDialogue(){learnTownNote('exchange');modal('Aurelia Ledgerpaw — Felin Exchange',`<p>“Road coin belongs in a purse. Savings belong behind stone, iron and three signatures.”</p><p>You have <strong>${current().bank.coins} banked crowns</strong>. Anything stored here remains available to this character whenever you return.</p><div class="dialogue-options"><button class="game-btn gold" data-open-bank>Open my vault</button><button class="game-btn" data-bank-note>How does the Exchange work?</button><button class="game-btn dark" data-bank-close>Farewell</button></div>`);modalLayer.querySelector('[data-open-bank]').addEventListener('click',bankDialogue);modalLayer.querySelector('[data-bank-note]').addEventListener('click',()=>showTownNote('exchange'));modalLayer.querySelector('[data-bank-close]').addEventListener('click',closeModal)}
function sellPrice(k){return Math.max(1,Math.floor((ITEMS[k]?.value||1)*.55*(1+(guildRank().market||0))))}
function sellableCount(k){const c=current();let n=countItem(k);if(c?.equipment?.weapon===k||c?.equipment?.body===k)n=Math.max(0,n-1);return n}
function sellItem(k){const it=ITEMS[k],n=sellableCount(k);if(!it||n<1){toast('That item is equipped or unavailable.');return}const price=sellPrice(k);removeItem(k,1);current().coins+=price;playSfx('coin',.7);saveCharacter();toast(`Sold ${it.name} for ${price} crowns.`);renderPanel();updateHud();closeModal();merchantDialogue()}
