function hearthDialogue(){const raw=countItem('river_dace');modal('Warm Saucer Hearth',`<p>The iron pan is already hot. Mina has left rosemary, salt and a long-handled fish turner beside the coals.</p><div class="shop-row"><div class="icon">🍢</div><div class="copy"><strong>Grill Silver Dace</strong><small>1 fresh Silver Dace • Cooking XP</small></div><button class="game-btn teal" data-hearth-one ${raw?'':'disabled'}>Cook one</button></div>${raw>1?`<div class="shop-row"><div class="icon">🔥</div><div class="copy"><strong>Cook all ${raw}</strong><small>Batch cooking</small></div><button class="game-btn" data-hearth-all>Cook all</button></div>`:''}`);const one=modalLayer.querySelector('[data-hearth-one]');if(one)one.addEventListener('click',()=>cookFish(1));const all=modalLayer.querySelector('[data-hearth-all]');if(all)all.addEventListener('click',()=>cookFish(raw))}
function bedDialogue(){modal('Guest Room',`<p>A small curtained bed, a washbasin and a brass candleholder. Mina charges five crowns for the night.</p><div class="dialogue-options"><button class="game-btn gold" data-sleep-bed>Sleep until seven bells — 5 ◈</button><button class="game-btn dark" data-leave-bed>Not yet</button></div>`);modalLayer.querySelector('[data-sleep-bed]').addEventListener('click',restAtInn);modalLayer.querySelector('[data-leave-bed]').addEventListener('click',closeModal)}
function innkeeperDialogue(){const st=questState('river_supper'),prog=questProgress('river_supper'),raw=countItem('river_dace');let quest='';if(st==='available')quest=`<button class="game-btn gold" data-accept-supper>Accept “A Proper Supper”</button>`;else if(st==='active'&&prog.complete)quest=`<button class="game-btn gold" data-claim-supper>Serve Mina the supper</button>`;else if(st==='active')quest=`<button class="game-btn dark" disabled>Progress: ${prog.text}</button>`;modal('Mina Whiskerpot — Warm Saucer',`<p>“A full belly makes a steadier sword paw. If you catch anything silver in the river, I can show you what a proper pan does to it.”</p>${quest}<div class="shop-row"><div class="icon">🍢</div><div class="copy"><strong>Grill Silver Dace</strong><small>1 fresh Silver Dace • Cooking XP</small></div><button class="game-btn teal" data-cook-one ${raw?'':'disabled'}>Cook one</button></div>${raw>1?`<div class="shop-row"><div class="icon">🔥</div><div class="copy"><strong>Cook all ${raw}</strong><small>Batch cooking</small></div><button class="game-btn" data-cook-all>Cook all</button></div>`:''}<div class="dialogue-options"><button class="game-btn" data-river-lore>Ask about the Silver River</button><button class="game-btn dark" data-rest>Rent a room until morning — 5 ◈</button></div>`);const a=modalLayer.querySelector('[data-accept-supper]');if(a)a.addEventListener('click',()=>acceptQuest('river_supper'));const q=modalLayer.querySelector('[data-claim-supper]');if(q)q.addEventListener('click',()=>claimQuest('river_supper'));const one=modalLayer.querySelector('[data-cook-one]');if(one)one.addEventListener('click',()=>cookFish(1));const all=modalLayer.querySelector('[data-cook-all]');if(all)all.addEventListener('click',()=>cookFish(raw));modalLayer.querySelector('[data-river-lore]').addEventListener('click',()=>showTownNote('river_trade'));modalLayer.querySelector('[data-rest]').addEventListener('click',restAtInn)}
function restAtInn(){const c=current();if(c.coins<5){toast('You need 5 crowns for a room.');return}c.coins-=5;c.hp=c.maxHp;c.focus=playerFocusMax();const base=Math.floor(c.world.timeMinutes/1440)*1440,mod=c.world.timeMinutes%1440;c.world.timeMinutes=(mod<420?base+420:base+1440+420);saveCharacter();closeModal();toast(`You sleep until seven bells on ${worldDayName()}. Health and Focus restored.`);updateHud()}
function buyItem(item,price){const c=current();if(c.coins<price){toast('Not enough crowns.');return false}c.coins-=price;addItem(item,1);playSfx('coin',.55);saveCharacter();toast(`Bought ${ITEMS[item].name}.`);updateHud();renderPanel();return true}
function buyFairItem(item,price){if(!buyItem(item,price))return false;closeModal();marketStallDialogue();return true}
function buyFairStack(item,count,price){const c=current();if(c.coins<price){toast('Not enough crowns.');return false}c.coins-=price;addItem(item,count);playSfx('coin',.45);saveCharacter();toast(`Bought ${count} × ${ITEMS[item].name}.`);updateHud();renderPanel();closeModal();marketStallDialogue();return true}
function buyStack(item,count,price){const c=current();if(c.coins<price){toast('Not enough crowns.');return}c.coins-=price;addItem(item,count);playSfx('coin',.45);saveCharacter();closeModal();toast(`Bought ${count} × ${ITEMS[item].name}.`);renderPanel();updateHud();merchantDialogue()}
function masterworkDialogue(){const c=current(),unlocked=questState('makers_mark')==='claimed';const canChar=countItem('oak_log')>=2,canSteel=c.skills.smithing.level>=4&&countItem('iron_ore')>=2&&countItem('charcoal')>=1,canLine=c.skills.tailoring.level>=4&&countItem('fox_pelt')>=2&&countItem('reed')>=2;const recipes=[['masterwork_sabre','Masterwork Quarry Sabre','Smithing 5 / Crafting 4 • Quarry Sabre + 2 Steel + 1 Oil',c.skills.smithing.level>=5&&c.skills.crafting.level>=4&&countItem('gilded_quarry_sabre')>=1&&countItem('steel_billet')>=2&&countItem('lavender_oil')>=1],['reinforced_brigandine','Reinforced Brigandine','Smithing 5 / Tailoring 4 • Brigandine + 2 Steel + 1 Lining',c.skills.smithing.level>=5&&c.skills.tailoring.level>=4&&countItem('brigandine_doublet')>=1&&countItem('steel_billet')>=2&&countItem('leather_lining')>=1],['bellflower_recurve','Bellflower Recurve','Crafting 5 / Tailoring 4 • Longbow + Lining + 2 Oak + Oil',c.skills.crafting.level>=5&&c.skills.tailoring.level>=4&&countItem('guild_longbow')>=1&&countItem('leather_lining')>=1&&countItem('oak_log')>=2&&countItem('lavender_oil')>=1],['oiled_foxhide','Oiled Foxhide Jerkin','Tailoring 5 • Foxhide Jerkin + Lining + Oil',c.skills.tailoring.level>=5&&countItem('foxhide_jerkin')>=1&&countItem('leather_lining')>=1&&countItem('lavender_oil')>=1],['aetherglass_wand','Aetherglass Wand','Alchemy 5 / Crafting 4 • Hermetic Wand + Lens + Steel',c.skills.alchemy.level>=5&&c.skills.crafting.level>=4&&countItem('hermetic_wand')>=1&&countItem('aether_lens')>=1&&countItem('steel_billet')>=1],['aetherwoven_coat','Aetherwoven Scholar Coat','Alchemy 5 / Tailoring 4 • Scholar Coat + Lens + Oil + 2 Reed',c.skills.alchemy.level>=5&&c.skills.tailoring.level>=4&&countItem('scholar_coat')>=1&&countItem('aether_lens')>=1&&countItem('lavender_oil')>=1&&countItem('reed')>=2]];modal('Ironpaw Masterwork Bench',`<p>“Raw ore makes equipment,” Bia says. “Refined stock makes something worth stamping.”</p><h3 class="trade-heading">Refinement</h3><div class="shop-row"><div class="icon">⬛</div><div class="copy"><strong>2 Forge Charcoal</strong><small>2 Oak Logs • Crafting 3</small></div><button class="game-btn" data-refine="charcoal" ${c.skills.crafting.level>=3&&canChar?'':'disabled'}>Burn</button></div><div class="shop-row"><div class="icon">▰</div><div class="copy"><strong>Quarry Steel Billet</strong><small>Smithing 4 • 2 Iron + 1 Charcoal</small></div><button class="game-btn teal" data-refine="steel_billet" ${canSteel?'':'disabled'}>Refine</button></div><div class="shop-row"><div class="icon">🪡</div><div class="copy"><strong>Foxhide Lining</strong><small>Tailoring 4 • 2 Pelts + 2 Reed</small></div><button class="game-btn teal" data-refine="leather_lining" ${canLine?'':'disabled'}>Cut</button></div><h3 class="trade-heading">Guild Masterworks</h3>${unlocked?recipes.map(([id,name,desc,ok])=>`<div class="shop-row"><div class="icon">${ITEMS[id].icon}</div><div class="copy"><strong>${name}</strong><small>${desc}</small></div><button class="game-btn gold" data-masterwork="${id}" ${ok?'':'disabled'}>Upgrade</button></div>`).join(''):`<div class="quest-item"><strong>Maker's Seal required</strong><p>Complete “A Maker's Mark” for Bia to unlock permanent masterwork upgrades.</p></div>`}<div class="dialogue-options"><button class="game-btn dark" data-masterwork-lore>Read Bia’s notes on masterworks</button></div>`);modalLayer.querySelectorAll('[data-refine]').forEach(b=>b.addEventListener('click',()=>refineMaterial(b.dataset.refine)));modalLayer.querySelectorAll('[data-masterwork]').forEach(b=>b.addEventListener('click',()=>craftMasterwork(b.dataset.masterwork)));modalLayer.querySelector('[data-masterwork-lore]').addEventListener('click',()=>showTownNote('masterworks'))}
function refineMaterial(item){const c=current();let made=1;if(item==='charcoal'){if(c.skills.crafting.level<3||countItem('oak_log')<2)return;removeItem('oak_log',2);made=2;addItem('charcoal',2);addSkillXp('crafting',20);addSkillXp('woodcutting',4)}else if(item==='steel_billet'){if(c.skills.smithing.level<4||countItem('iron_ore')<2||countItem('charcoal')<1)return;removeItem('iron_ore',2);removeItem('charcoal',1);addItem('steel_billet',1);addSkillXp('smithing',36);addSkillXp('crafting',10)}else if(item==='leather_lining'){if(c.skills.tailoring.level<4||countItem('fox_pelt')<2||countItem('reed')<2)return;removeItem('fox_pelt',2);removeItem('reed',2);addItem('leather_lining',1);addSkillXp('tailoring',38);addSkillXp('crafting',10)}else return;c.counters.crafted[item]=(c.counters.crafted[item]||0)+made;addPlayerXp(8+made*2);playSfx(item==='steel_billet'?'mine_strike':'gather',.7);saveCharacter();closeModal();toast(`Refined ${made>1?made+' × ':''}${ITEMS[item].name}.`);renderPanel();updateHud()}
function craftMasterwork(item){const c=current();if(questState('makers_mark')!=='claimed')return;const consume=(req)=>{for(const[k,n]of Object.entries(req))if(countItem(k)<n)return false;for(const[k,n]of Object.entries(req))removeItem(k,n);return true};let req=null,skills={};if(item==='masterwork_sabre'){req={gilded_quarry_sabre:1,steel_billet:2,lavender_oil:1};skills={smithing:5,crafting:4}}else if(item==='reinforced_brigandine'){req={brigandine_doublet:1,steel_billet:2,leather_lining:1};skills={smithing:5,tailoring:4}}else if(item==='bellflower_recurve'){req={guild_longbow:1,leather_lining:1,oak_log:2,lavender_oil:1};skills={crafting:5,tailoring:4}}else if(item==='oiled_foxhide'){req={foxhide_jerkin:1,leather_lining:1,lavender_oil:1};skills={tailoring:5}}else if(item==='aetherglass_wand'){req={hermetic_wand:1,aether_lens:1,steel_billet:1};skills={alchemy:5,crafting:4}}else if(item==='aetherwoven_coat'){req={scholar_coat:1,aether_lens:1,lavender_oil:1,reed:2};skills={alchemy:5,tailoring:4}}else return;for(const[k,n]of Object.entries(skills))if((c.skills[k]?.level||1)<n)return;if(!consume(req))return;addItem(item,1);const base=Object.keys(req).find(k=>ITEMS[k]?.attack!=null||ITEMS[k]?.defense!=null);if(base&&c.equipment.weapon===base)c.equipment.weapon=item;if(base&&c.equipment.body===base)c.equipment.body=item;c.focus=Math.min(c.focus,playerFocusMax());c.counters.crafted[item]=(c.counters.crafted[item]||0)+1;for(const k of Object.keys(skills))addSkillXp(k,42);addPlayerXp(22);playSfx(item.includes('coat')||item.includes('foxhide')?'gather':'mine_strike',.85);saveCharacter();closeModal();toast(`Masterwork completed: ${ITEMS[item].name}.`);renderPanel();updateHud()}
function craftItem(item){const c=current();let made=1;if(item==='iron_rapier'){if(countItem('iron_ore')<3||countItem('oak_log')<1)return;removeItem('iron_ore',3);removeItem('oak_log',1);addItem(item,1);addSkillXp('smithing',24);addSkillXp('crafting',10);addPlayerXp(8)}else if(item==='padded_doublet'){if(countItem('reed')<3)return;removeItem('reed',3);addItem(item,1);addSkillXp('tailoring',24);addSkillXp('crafting',10);addPlayerXp(8)}else if(item==='tempered_rapier'){if(questState('iron_and_oak')!=='claimed'||c.skills.smithing.level<3||countItem('iron_ore')<5||countItem('oak_log')<2)return;removeItem('iron_ore',5);removeItem('oak_log',2);addItem(item,1);addSkillXp('smithing',36);addSkillXp('crafting',16);addPlayerXp(12)}else if(item==='brigandine_doublet'){if(questState('redtail_problem')!=='claimed'||c.skills.smithing.level<3||c.skills.tailoring.level<3||countItem('iron_ore')<4||countItem('fox_pelt')<2)return;removeItem('iron_ore',4);removeItem('fox_pelt',2);addItem(item,1);addSkillXp('smithing',28);addSkillXp('tailoring',32);addSkillXp('crafting',18);addPlayerXp(14)}else if(item==='shortbow'){if(countItem('oak_log')<3||countItem('reed')<2)return;removeItem('oak_log',3);removeItem('reed',2);addItem(item,1);addSkillXp('crafting',24);addPlayerXp(8)}else if(item==='arrow'){if(countItem('oak_log')<1||countItem('reed')<1)return;removeItem('oak_log',1);removeItem('reed',1);made=12;addItem('arrow',made);addSkillXp('crafting',16);addPlayerXp(5)}else if(item==='guild_longbow'){if(questState('long_watch')!=='claimed'||c.skills.crafting.level<3||countItem('oak_log')<4||countItem('reed')<2)return;removeItem('oak_log',4);removeItem('reed',2);addItem(item,1);addSkillXp('crafting',38);addPlayerXp(14)}else if(item==='foxhide_jerkin'){if(c.skills.tailoring.level<3||countItem('fox_pelt')<3||countItem('reed')<2)return;removeItem('fox_pelt',3);removeItem('reed',2);addItem(item,1);addSkillXp('tailoring',36);addSkillXp('crafting',12);addPlayerXp(12)}else if(item==='quarry_crossbow'){if(questState('beneath_quarry')!=='claimed'||c.skills.smithing.level<4||c.skills.crafting.level<3||countItem('iron_ore')<5||countItem('oak_log')<3)return;removeItem('iron_ore',5);removeItem('oak_log',3);addItem(item,1);addSkillXp('smithing',42);addSkillXp('crafting',36);addPlayerXp(18)}else if(item==='bolt'){if(countItem('iron_ore')<1||countItem('oak_log')<1)return;removeItem('iron_ore',1);removeItem('oak_log',1);made=10;addItem('bolt',made);addSkillXp('smithing',12);addSkillXp('crafting',14);addPlayerXp(5)}else return;c.counters.crafted[item]=(c.counters.crafted[item]||0)+made;playSfx(['iron_rapier','tempered_rapier','brigandine_doublet','quarry_crossbow','bolt'].includes(item)?'mine_strike':'gather',.6);saveCharacter();closeModal();toast(`Created ${made>1?made+' × ':''}${ITEMS[item].name}.`);renderPanel()}
function quarrymasterDialogue(){const st=questState('redtail_problem'),prog=questProgress('redtail_problem'),deep=questState('beneath_quarry'),deepProg=questProgress('beneath_quarry');let quest='';if(st==='available')quest=`<button class="game-btn gold" data-accept-redtail>Accept “The Redtail Problem”</button>`;else if(st==='active'&&prog.complete)quest=`<button class="game-btn gold" data-claim-redtail>Report the quarry cleared</button>`;else if(st==='active')quest=`<button class="game-btn dark" disabled>Progress: ${prog.text}</button>`;else if(st==='locked')quest=`<p class="small muted">Gesso is waiting for Bia Ironpaw to sponsor you for Eastroad work.</p>`;else if(deep==='available')quest=`<button class="game-btn gold" data-accept-underworks>Accept “Beneath the Old Quarry”</button>`;else if(deep==='active'&&deepProg.complete)quest=`<button class="game-btn gold" data-claim-underworks>Return the lost guild seal</button>`;else if(deep==='active')quest=`<button class="game-btn dark" disabled>Underworks: ${deepProg.text}</button>`;else quest=`<button class="game-btn dark" disabled>Quarry contracts completed</button>`;const intro=st==='claimed'?`“You cleared the Redtails, but that opened an older problem. There is a sealed stair in the east face. Rats have been hauling guild brass out of the Underworks.”`:`“The shallow seams are picked clean. Mining 3 gets you into the rich faces. Just mind the Redtails — their captain thinks the quarry belongs to him.”`;modal('Quarrymaster Gesso — Old Quarry',`<p>${intro}</p>${quest}<div class="dialogue-options"><button class="game-btn dark" data-close-gesso>Back to work</button></div>`);const a=modalLayer.querySelector('[data-accept-redtail]');if(a)a.addEventListener('click',()=>acceptQuest('redtail_problem'));const q=modalLayer.querySelector('[data-claim-redtail]');if(q)q.addEventListener('click',()=>claimQuest('redtail_problem'));const da=modalLayer.querySelector('[data-accept-underworks]');if(da)da.addEventListener('click',()=>acceptQuest('beneath_quarry'));const dq=modalLayer.querySelector('[data-claim-underworks]');if(dq)dq.addEventListener('click',()=>claimQuest('beneath_quarry'));modalLayer.querySelector('[data-close-gesso]').addEventListener('click',closeModal)}
function gatherResource(o){const c=current(),rs=c.world.resources[o.id];if(rs.readyAt>Date.now()){toast('That resource is recovering.');return}const kind=prop(o,'resource');let item=kind,skill='foraging',xp=8,amount=1,cooldown=3500,req=1,sfx='gather';if(kind==='oak_log'){skill='woodcutting';xp=10;sfx='wood_chop'}else if(kind==='old_oak'){item='oak_log';skill='woodcutting';xp=18;amount=2;cooldown=8500;req=3;sfx='wood_chop'}else if(kind==='iron_ore'){skill='mining';xp=11;sfx='mine_strike'}else if(kind==='rich_iron'){item='iron_ore';skill='mining';xp=20;amount=2;cooldown=9000;req=3;sfx='mine_strike'}else if(kind==='river_dace'){skill='fishing';xp=12;cooldown=4800;sfx='fish_splash'}else if(kind==='lavender'){skill='foraging';xp=12;cooldown=5200;req=2}else if(kind==='reed'||kind==='grape'||kind==='rosemary'){skill='foraging';xp=8}if(c.skills[skill].level<req){toast(`${SKILL_NAMES[skill]} level ${req} is required here.`);return}if(Math.random()<Math.min(.35,c.skills[skill].level*.035))amount++;if(kind==='river_dace'&&worldEventActive('river'))amount++;if(kind==='river_dace'&&currentWeather()==='rain'&&MAPS[APP.mapId]?.outdoor){amount++;recordFieldcraftAction('weather_rain_casts')}if((kind==='rosemary'||kind==='lavender')&&currentWeather()==='mist'&&MAPS[APP.mapId]?.outdoor)recordFieldcraftAction('weather_mist_herbs');addItem(item,amount);c.counters.gathered[item]=(c.counters.gathered[item]||0)+amount;if(kind==='river_dace'&&worldEventActive('river'))recordFestivalAction('river_casts',1);if(kind==='lavender'&&worldEventActive('vale'))recordFestivalAction('vale_lavender',amount);rs.readyAt=Date.now()+cooldown;addSkillXp(skill,xp);addPlayerXp(kind==='old_oak'||kind==='rich_iron'?5:3);const ctr=objectCenter(o),fish=kind==='river_dace';addBurst(ctr.x,ctr.y-12,fish?'#8fc7d2':kind.includes('iron')?'#c7c7bd':'#b9c77b',kind==='old_oak'||kind==='rich_iron'?11:8);addFloater(ctr.x,ctr.y-34,`+${amount} ${ITEMS[item].name}`,fish?'#b9e2eb':'#d9e7a5');playSfx(sfx,.72);saveCharacter();APP.log=fish?`Caught ${amount} × ${ITEMS[item].name}.`:`Gathered ${amount} × ${ITEMS[item].name}.`;toast(APP.log);renderPanel()}
function equippedWeapon(){return ITEMS[current()?.equipment?.weapon]||ITEMS.worn_rapier}
function weaponStyle(){return equippedWeapon().style||'melee'}
function disciplineActive(id){return current()?.discipline===id}
function disciplineUnlocked(id,c=current()){const d=DISCIPLINES[id];if(!c||!d)return false;return Object.entries(d.req).every(([k,n])=>(c.skills[k]?.level||1)>=n)}
function disciplineReqText(id){const d=DISCIPLINES[id];return Object.entries(d.req).map(([k,n])=>`${SKILL_NAMES[k]} ${n}`).join(' • ')}
function playerFocusMax(){const c=current(),body=ITEMS[c?.equipment?.body]||{};return Math.max(30,(c?.maxFocus||30)+(body.focusBonus||0)+(disciplineActive('hermeticist')?10:0))}
function playerAttackRange(){const w=equippedWeapon();return w.style==='ranged'||w.style==='magic'?(w.range||210):86}
function playerAttackInterval(){const w=equippedWeapon();return w.style==='ranged'||w.style==='magic'?(w.speed||1000):1000}
function rangedAccuracy(){const c=current(),w=equippedWeapon(),body=ITEMS[c.equipment.body]||{};return clamp(.86+c.skills.archery.level*.012+(w.accuracy||0)+(body.rangedAccuracy||0)+(disciplineActive('ranger')?.08:0)-(MAPS[APP.mapId]?.outdoor&&currentWeather()==='wind'?Math.max(0,.08-(body.windProtection||0)):0),.62,.985)}
function magicAccuracy(){const c=current(),w=equippedWeapon(),body=ITEMS[c.equipment.body]||{};return clamp(.84+c.skills.aethercraft.level*.014+(w.accuracy||0)+(body.magicAccuracy||0)-(body.defense||0)*.012+(disciplineActive('hermeticist')?.08:0),.60,.99)}
function startCombat(o){const c=current(),ws=c.world.enemies[o.id];if(!ws?.alive)return;if(APP.combat.enemyId!==o.id)APP.combat.telegraph=null;APP.combat.enemyId=o.id;APP.selectedObjectId=o.id;const style=weaponStyle(),ammo=equippedWeapon().ammo;APP.log=`Targeting ${o.name}. ${style==='ranged'?`Keep your distance • ${countItem(ammo)} ammo ready.`:style==='magic'?`Aethercraft ready • ${Math.floor(c.focus)}/${playerFocusMax()} Focus.`:'Watch for heavy attacks and Guard at the right moment.'}`;const ctr=objectCenter(o),range=playerAttackRange();APP.pendingInteraction=null;if(dist(c.position.x,c.position.y,ctr.x,ctr.y)>range)setNavigation(ctr.x,ctr.y,Math.max(64,range-20),o.id,false,true,true);else if(navLineClear(c.position,ctr))clearNavigation(false);else setNavigation(ctr.x,ctr.y,Math.max(64,range-20),o.id,false,true,true);updateHud()}
