function updateHotbarState(){if(APP.screen!=='game')return;const now=performance.now(),w=equippedWeapon(),style=w.style||'melee',ranged=style==='ranged',magic=style==='magic',f=document.querySelector('[data-hot="flourish"]'),g=document.querySelector('[data-hot="guard"]'),a=document.querySelector('[data-hot="attack"]');if(a){a.title=ranged?`Shoot • ${countItem(w.ammo)} ${ITEMS[w.ammo].name}`:magic?`Cast • ${Math.floor(current().focus)}/${playerFocusMax()} Focus`:'Attack';a.innerHTML=`<span>1</span>${ranged?'🏹':magic?'✧':'⚔'}`}if(f){f.classList.toggle('cooldown',now<APP.combat.flourishReadyAt);f.title=ranged?'Aimed Shot':magic?'Arc Burst':'Flourish';f.innerHTML=`<span>2</span>${ranged?'◎':magic?'◉':'✦'}`}if(g){g.classList.toggle('cooldown',now<APP.combat.guardReadyAt);g.classList.toggle('guarding',now<APP.combat.guardUntil)}}
