function addItem(k,n=1){const c=current();c.inventory[k]=(c.inventory[k]||0)+n} function removeItem(k,n=1){const c=current();c.inventory[k]=Math.max(0,(c.inventory[k]||0)-n);if(c.inventory[k]===0)delete c.inventory[k]} function countItem(k){return current()?.inventory[k]||0}
